-- STOCK MARKET ANALYSIS | Srija Chatterjee | 10 October 2026
-- Original supplied data: six stocks, 889 trading days each, 2015-01-01 to 2018-07-31.
-- All 13 student-guide tasks plus adjusted signals, quick reversals and risk diagnostics.
-- Embedded INSERTs make this file reproducible: no CSV path or LOCAL INFILE setting is needed.
-- Raw tables preserve the original data. Adjusted prices divide pre-event OHLC by 2.
-- Prices exclude dividends, costs and taxes. Historical signals are not current advice.
-- Tasks 5/7 round Bajaj averages to 2 decimals as requested. Task 10 uses full precision.
-- SQLite 3.25+ with math functions. python build_project.py uses Python's bundled SQLite.
DROP VIEW IF EXISTS v_signal_changes;
DROP VIEW IF EXISTS v_crossovers;
DROP VIEW IF EXISTS v_stock_summary;
DROP VIEW IF EXISTS v_analytics;
DROP VIEW IF EXISTS v_price_basis;
DROP VIEW IF EXISTS v_prices;

DROP TABLE IF EXISTS bajaj_auto;
CREATE TABLE bajaj_auto (
    `date` TEXT PRIMARY KEY,
    `open_price` REAL,
    `high_price` REAL,
    `low_price` REAL,
    `close_price` REAL,
    `wap` REAL,
    `no_of_shares` INTEGER,
    `no_of_trades` INTEGER,
    `total_turnover` REAL,
    `deliverable_qty` INTEGER,
    `pct_deli_qty` REAL,
    `spread_high_low` REAL,
    `spread_close_open` REAL
);

